/**
 * @file logger.h
 * @brief Public interface for logging backends in osdp-cli.
 *
 * This module exposes the initialization and lifecycle management functions for the logging backends available in the application.
 *
 * The logging architecture is event-driven: protocol events generated by the OSDP core are dispatched to one or more registered logger
 * backends through the internal event system.
 *
 * Supported logging backends currently include:
 *   - console logger for interactive terminal output
 *   - file logger for persistent frame capture
 *   - sniff-specific loggers for dedicated capture sessions
 *
 * Each backend operates independently and may render or store protocol events using its own formatting strategy.
 */

#ifndef LOGGER_H
#define LOGGER_H


/**
 * @brief Initialize the console logging backend.
 *
 * Registers the console logger as an OSDP event listener. Captured protocol events will be rendered to the terminal using the active
 * console rendering mode.
 *
 * @param user_data Pointer to a user-defined context structure, typically the CLI runtime context, forwarded to the logger callback.
 */
void logger_console_init(void *user_data);

/**
 * @brief Initialize the file logging backend.
 *
 * Opens the configured output file and registers the file logger as an OSDP event listener.
 *
 * Once initialized, emitted protocol events are written to the associated log file.
 *
 * @param user_data Pointer to a user-defined context structure.
 *
 * @return 0 on success, non-zero on failure.
 */
int logger_file_init(void *user_data);

/**
 * @brief Shutdown the file logging backend.
 *
 * Flushes pending data and closes the active log file associated with the file logger backend.
 */
void logger_file_close(void);


/**
 * @brief Initialize the console logging backend specific to the sniff command.
 *
 * Registers the console logger as an OSDP event listener. Captured protocol events will be rendered to the terminal using the active
 * console rendering mode.
 *
 * @param user_data Pointer to a structure representing the "sniff" command option forwarded to the logger callback.
 */
void sniff_logger_console_init(void *user_data);

/**
 * @brief Initialize the file logging backend specific to the sniff command.
 *
 * Opens the configured output file and registers the file logger as an OSDP event listener.
 *
 * Once initialized, emitted protocol events are written to the associated log file.
 *
 * @param user_data Pointer to a structure representing the "sniff" command option forwarded to the logger callback.
 *
 * @return 0 on success, non-zero on failure.
 */
int sniff_logger_file_init(void *user_data);

/**
 * @brief Shutdown the file logging backend specific to the sniff command.
 *
 * Flushes pending data and closes the active log file associated with the file logger backend.
 */
void sniff_logger_file_close(void);

#endif // LOGGER_H